input.script:
export const meta = {
  name: 'tiny-two-word-echo',
  description: 'Two agents each echo a single word, then stop',
  phases: [
    { title: 'Echo', detail: 'two agents, one word each' },
  ],
}

phase('Echo')

const results = await parallel([
  () =>
    agent('Return exactly the single word: ping\nNo punctuation, no explanation, no other text.', {
      label: 'echo-ping',
      phase: 'Echo',
      effort: 'low',
    }),
  () =>
    agent('Return exactly the single word: pong\nNo punctuation, no explanation, no other text.', {
      label: 'echo-pong',
      phase: 'Echo',
      effort: 'low',
    }),
])

const words = results.filter(Boolean).map((r) => String(r).trim())
log(`echoed words: ${JSON.stringify(words)}`)
